'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['selectBuildPages']);
const { selectBuildPages } = api;

const manifest = [
  { slug: 'home', revision: 0, content: 'Home' },
  { slug: 'about', revision: Number.MAX_SAFE_INTEGER, content: '' },
  { slug: 'contact', revision: 3, content: ' Contact ' }
];
const snapshot = manifest.map((page) => ({ ...page }));
const requested = ['contact', 'home'];
const selected = selectBuildPages(manifest, requested);
assert.deepStrictEqual(selected, [
  { slug: 'contact', revision: 3, content: ' Contact ' },
  { slug: 'home', revision: 0, content: 'Home' }
]);
assert.deepStrictEqual(manifest, snapshot);
assert.deepStrictEqual(requested, ['contact', 'home']);
assert.notStrictEqual(selected[0], manifest[2]);
assert.notStrictEqual(selected[1], manifest[0]);
selected[0].content = 'changed';
assert.strictEqual(manifest[2].content, ' Contact ');
assert.deepStrictEqual(selectBuildPages([], []), []);
assert.deepStrictEqual(selectBuildPages(manifest, []), []);

for (const args of [[null, []], [[], null], [{}, []], [[], 'home']]) {
  assert.throws(() => selectBuildPages(...args), TypeError);
}
for (const badPage of [
  null,
  [],
  { slug: '', revision: 0, content: 'x' },
  { slug: 1, revision: 0, content: 'x' },
  { slug: 'x', revision: -1, content: 'x' },
  { slug: 'x', revision: 1.5, content: 'x' },
  { slug: 'x', revision: Number.MAX_SAFE_INTEGER + 1, content: 'x' },
  { slug: 'x', revision: 0, content: 2 }
]) assert.throws(() => selectBuildPages([badPage], []), TypeError);
assert.throws(() => selectBuildPages([
  { slug: 'x', revision: 0, content: 'one' },
  { slug: 'x', revision: 1, content: 'two' }
], []), RangeError);
assert.throws(() => selectBuildPages(manifest, ['']), TypeError);
assert.throws(() => selectBuildPages(manifest, [1]), TypeError);
assert.throws(() => selectBuildPages(manifest, ['home', 'home']), RangeError);
assert.throws(() => selectBuildPages(manifest, ['missing']), RangeError);
assert.throws(() => selectBuildPages([], ['missing']), RangeError);

